import { readFileSync } from 'node:fs';

// The invoice screen: the page views/invoice.html, filled in for one invoice.
const PAGE = readFileSync(new URL('../views/invoice.html', import.meta.url), 'utf8');

// fill(text, name, value): text with every {{name}} replaced by value.
const fill = (text, name, value) => text.split(`{{${name}}}`).join(value);

// money(total): a numeric total with two decimals; any other value as it was shown before.
const money = (total) =>
  total !== null && total !== '' && Number.isFinite(Number(total)) ? Number(total).toFixed(2) : String(total);

export const invoiceView = (invoice) => fill(fill(PAGE, 'id', String(invoice.id)), 'total', money(invoice.total));
EOF
